import React from "react";

const Footer = () => {
  return (
    <footer className="mt-12 border-t border-slate-700/30 bg-slate-900 text-slate-200">
      <div className="mx-auto w-full max-w-7xl px-4 py-5 text-center text-sm sm:px-6 lg:px-8">
        <p className="font-medium tracking-wide">FAST Sports System, Copyright &copy; 2026</p>
      </div>
    </footer>
  );
};

export default Footer;
